    11	  validateUser(user) {
    12	    super.validateUser(user);
    13	    if (!user.email || !user.email.includes('@')) {
    14	      throw new TypeError('user.email is required for email notifications');
    15	    }
    16	  }
    17	
    18	  shouldThrottle(user, message, options = {}) {
    19	    const base = super.shouldThrottle(user, message, options);
    20	    if (base.throttled) {
    21	      return base;
    22	    }
    23	
    24	    if (message.category === 'marketing' && !user.emailOptIn) {
    25	      return {
    26	        throttled: true,
    27	        reason: 'user has not opted into marketing email',
    28	        retryAt: null
    29	      };
    30	    }
    31	
    32	    return { throttled: false };
    33	  }
    34	
    35	  format(user, message, options = {}) {
    36	    const formatted = super.format(user, message, options);
