const { createHourlyThrottle } = require('./throttle');

// A channel definition supplies the channel-specific pieces; this module owns
// the shared send pipeline (validate, throttle, format, deliver, record).
//
// Definition shape:
//   name               channel id, also the transport function key
//   label              channel name used in the missing-transport error
//   defaultMaxPerHour  hourly limit when options.maxPerHour is not set
//   configure(options)                   -> channel settings
//   validateUser(user)                   throws on channel-specific problems
//   bypassThrottle(user, message, opts)  optional; true skips all throttling
//   optOutReason(user, message)          optional; string blocks the send
//   format(base, { user, message, options, settings, now }) -> payload
function createChannelNotifier(definition, options = {}) {
  const channel = definition.name;
  const transport = options.transport || {};
  const now = options.now || (() => new Date());
  const defaultLocale = options.defaultLocale || 'en-US';
  const throttle = createHourlyThrottle({
    channel,
    store: options.throttleStore || new Map(),
    now,
    maxPerHour: options.maxPerHour || definition.defaultMaxPerHour
  });
  const settings = definition.configure(options);

  function checkThrottle(user, message, sendOptions) {
    if (definition.bypassThrottle && definition.bypassThrottle(user, message, sendOptions)) {
      return { throttled: false };
    }

    const limit = throttle.check(user, message, sendOptions);
    if (limit.throttled) {
      return limit;
    }

    const reason = definition.optOutReason && definition.optOutReason(user, message);
    if (reason) {
      return { throttled: true, reason, retryAt: null };
    }

    return { throttled: false };
  }

  function formatBase(user, message, sendOptions) {
    const id = `${channel}-${user.id}-${now().getTime()}`;
    const locale = sendOptions.locale || user.locale || defaultLocale;
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);

    return {
      id,
      channel,
      locale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, 120),
      metadata: {
        category: message.category || 'general',
        priority: message.priority || 'normal',
        generatedAt: now().toISOString()
      }
    };
  }

  async function deliver(payload) {
    if (typeof transport[channel] !== 'function') {
      throw new Error(`${definition.label} transport is not configured`);
    }
    await transport[channel](payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    definition.validateUser(user);
    validateMessage(message);

    const throttled = checkThrottle(user, message, sendOptions);
    if (throttled.throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttled.reason,
        retryAt: throttled.retryAt,
        userId: user.id
      };
    }

    const base = formatBase(user, message, sendOptions);
    const payload = definition.format(base, { user, message, options: sendOptions, settings, now });
    await deliver(payload);
    throttle.record(user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: payload.id,
      preview: payload.preview
    };
  }

  return { channel, send };
}

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

module.exports = { createChannelNotifier };

