const emailChannel = {
  name: 'email',
  label: 'email',
  defaultMaxPerHour: 8,

  configure(options) {
    return {
      from: options.from || 'noreply@example.com',
      replyTo: options.replyTo || 'support@example.com',
      unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
    };
  },

  validateUser(user) {
    if (!user.email || !user.email.includes('@')) {
      throw new TypeError('user.email is required for email notifications');
    }
  },

  optOutReason(user, message) {
    if (message.category === 'marketing' && !user.emailOptIn) {
      return 'user has not opted into marketing email';
    }
    return null;
  },

  format(base, { user, message, settings }) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(user, message, settings.unsubscribeBaseUrl);

    return {
      ...base,
      to: user.email,
      from: settings.from,
      replyTo: settings.replyTo,
      subject: `${subjectPrefix}${base.title}`,
      text: `${base.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: base.body.slice(0, 90)
    };
  }
};

function footerFor(user, message, unsubscribeBaseUrl) {
  if (message.category === 'transactional' || message.category === 'security') {
