const util = require('node:util');
const [origPath, newPath] = process.argv.slice(2);
const impls = { orig: require(origPath), next: require(newPath) };

function serializeError(err) {
  return { error: err && err.constructor && err.constructor.name, message: err && err.message };
}

function makeClock(startIso, stepMs) {
  let t = new Date(startIso).getTime();
  const calls = [];
  const now = () => { const d = new Date(t); calls.push(t); t += stepMs; return d; };
  return { now, calls };
}

const channels = ['email', 'sms', 'slack', 'inapp'];

const factoryOptionSets = [
  () => ({}),
  () => ({ maxPerHour: 2 }),
  () => ({ maxPerHour: 1, defaultLocale: 'fr-FR', from: 'a@b.c', replyTo: 'r@b.c', unsubscribeBaseUrl: 'https://x.test/u',
           senderId: 'SND', segmentLength: 30, defaultWorkspace: 'ws', defaultChannel: '#dc', defaultIcon: 'star', defaultAction: '/act' }),
  () => ({ maxPerHour: 0, segmentLength: 0 }),
  () => ({ noTransport: true, maxPerHour: 2 }),
  () => ({ transportMissing: true, maxPerHour: 2 }),
  () => ({ transportThrows: true, maxPerHour: 2 }),
];

const users = {
  email: [
    { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true, locale: 'de-DE' },
    { id: 'u1', email: 'ava@example.com', emailOptIn: false },
    { id: 'a b&c', name: '$& $1 $$', email: 'x@y' },
    { id: 'u1', email: 'no-at-sign' },
    { id: 'u1', email: 12345 },
    { id: 'u1' },
    { email: 'ava@example.com' },
    { id: 0, email: 'a@b' },
    null,
    'string-user',
  ],
  sms: [
    { id: 'u2', name: 'Bo', phone: '+15551234567', smsOptIn: true },
    { id: 'u2', phone: '+15551234567', smsOptIn: false },
    { id: 'u2', phone: '555-1212' },
    { id: 'u2', phone: '+0123456789' },
    { id: 'u2', phone: '+123456' },
    { id: 'u2', phone: '+1234567890123456' },
    { id: 'u2' },
    null,
  ],
  slack: [
    { id: 'u3', name: 'Cy', slackId: 'U123', slackWorkspace: 'eng' },
    { id: 'u3', slackChannel: '#alerts' },
    { id: 'u3', slackId: 'U1', slackChannel: '#alerts' },
    { id: 'u3' },
    undefined,
  ],
  inapp: [
    { id: 'u4', name: 'Dee' },
    { id: 'u4', disabledInApp: true },
    { id: 'u4', locale: 'ja-JP', name: 'ダイ 🎉' },
    {},
    42,
  ],
};

const messages = [
  { title: 'Hello {{name}} {{id}}', body: 'Your {{category}} update {{name}} is ready', category: 'transactional' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Login <b>"x"</b> & y', body: '<script>alert(1)</script>', category: 'security' },
  { title: 'Urgent', body: 'B'.repeat(200), priority: 'urgent' },
  { title: 'A'.repeat(20), body: 'B'.repeat(40), priority: 'urgent', category: 'transactional' },
  { title: 'Marketing urgent', body: 'x', category: 'marketing', priority: 'urgent' },
  { title: 'Icon', body: 'Body 🎉 unicode', icon: 'gear', actionUrl: '/msg', category: 'release' },
  { title: 'T', body: '' },
  { title: '', body: 'B' },
  { title: 123, body: 456 },
  null,
  'not-an-object',
];

const sendOptionSets = [
  undefined,
  {},
  { force: true },
  { locale: 'es-ES', channel: '#ops', actionUrl: '/o', expiresInHours: 1 },
  { threadTs: '171234.0001' },
  { force: true, threadTs: '1', expiresInHours: 0 },
  null,
];

async function runScenario(impl, channel, makeFactoryOpts, user, message, sendOptions, sendCount) {
  const trace = { steps: [] };
  const raw = makeFactoryOpts();
  const clock = makeClock('2026-01-02T03:04:05.000Z', 20 * 60 * 1000);
  const log = [];
  const store = new Map();
  const opts = { ...raw, now: clock.now, throttleStore: store };
  delete opts.noTransport; delete opts.transportMissing; delete opts.transportThrows;
  if (!raw.noTransport) {
    const t = {};
    for (const c of channels) {
      t[c] = async function (payload) { log.push({ c, thisIsTransport: this === t, args: arguments.length, payload }); };
    }
    if (raw.transportMissing) delete t[channel];
    if (raw.transportThrows) t[channel] = async () => { throw new Error('boom'); };
    opts.transport = t;
  }
  let notifier;
  try {
    notifier = impl.createNotifier(channel, opts);
  } catch (err) {
    trace.create = serializeError(err);
    return trace;
  }
  trace.channelProp = notifier.channel;
  for (let i = 0; i < sendCount; i++) {
    try {
      const promise = sendOptions === undefined ? notifier.send(user, message) : notifier.send(user, message, sendOptions);
      trace.steps.push({ isPromise: promise instanceof Promise, result: await promise });
    } catch (err) {
      trace.steps.push(serializeError(err));
    }
  }
  trace.log = JSON.stringify(log);
  trace.store = JSON.stringify([...store.entries()]);
  trace.clockCalls = clock.calls;
  return trace;
}

(async () => {
  let scenarios = 0;
  const failures = [];
  for (const channel of channels) {
    for (const [fi, makeFactoryOpts] of factoryOptionSets.entries()) {
      for (const [ui, user] of users[channel].entries()) {
        for (const [mi, message] of messages.entries()) {
          for (const [si, sendOptions] of sendOptionSets.entries()) {
            scenarios++;
            const a = await runScenario(impls.orig, channel, makeFactoryOpts, user, message, sendOptions, 4);
            const b = await runScenario(impls.next, channel, makeFactoryOpts, user, message, sendOptions, 4);
            if (!util.isDeepStrictEqual(a, b)) {
              failures.push({ channel, fi, ui, mi, si, a, b });
            }
          }
        }
      }
    }
  }

  // Cross-channel scenarios: shared store via createAllNotifiers, window expiry and retryAt.
  for (const impl of Object.keys(impls)) void impl;
  const extra = async impl => {
    const out = {};
    const store = new Map();
    let t = new Date('2026-01-02T00:00:00.000Z').getTime();
    const now = () => new Date(t);
    const log = [];
    const transport = { email: async p => log.push(p), sms: async p => log.push(p), slack: async p => log.push(p), inapp: async p => log.push(p) };
    const all = impl.createAllNotifiers({ transport, throttleStore: store, now, maxPerHour: 1 });
    out.keys = Object.keys(all);
    out.registryKeys = Object.keys(impl.registry);
    const u = { id: 'x', email: 'x@y.z', phone: '+15551234567', slackId: 'U', emailOptIn: true, smsOptIn: true };
    const m = { title: 'T', body: 'B', category: 'general' };
    out.r = [];
    for (const c of out.keys) out.r.push(await all[c].send(u, m));
    for (const c of out.keys) out.r.push(await all[c].send(u, m));
    t += 30 * 60 * 1000;
    for (const c of out.keys) out.r.push(await all[c].send(u, m));
    t += 30 * 60 * 1000;
    for (const c of out.keys) out.r.push(await all[c].send(u, m));
    t += 1;
    for (const c of out.keys) out.r.push(await all[c].send(u, m, { force: true }));
    out.store = JSON.stringify([...store.entries()]);
    out.log = JSON.stringify(log);
    // Separate default stores per notifier when none is passed.
    const sep = impl.createAllNotifiers({ transport, now, maxPerHour: 1 });
    const sepA = await sep.email.send(u, m);
    const sepB = await impl.createNotifier('email', { transport, now, maxPerHour: 1 }).send(u, m);
    out.sep = [sepA.status, sepB.status, (await sep.email.send(u, m)).status];
    // Defaults with no options at all, real clock (compare shape only).
    const d = impl.createNotifier('inapp', { transport });
    const dr = await d.send({ id: 'd' }, { title: 't', body: 'b' });
    out.defaultShape = Object.keys(dr);
    out.unknown = [];
    for (const name of ['fax', undefined, '', 'EMAIL']) {
      try { impl.createNotifier(name); out.unknown.push('created'); } catch (e) { out.unknown.push(serializeError(e)); }
    }
    // Default options argument for factories.
    try { out.noArgs = Object.keys(impl.createAllNotifiers()); } catch (e) { out.noArgs = serializeError(e); }
    try { const n = impl.createNotifier('email'); out.noOpts = await n.send({ id: 'q', email: 'q@q' }, { title: 't', body: 'b' }).catch(serializeError); } catch (e) { out.noOpts = serializeError(e); }
    return out;
  };
  const ea = await extra(impls.orig);
  const eb = await extra(impls.next);
  if (!util.isDeepStrictEqual(ea, eb)) failures.push({ extra: true, a: ea, b: eb });

  console.log(`scenarios=${scenarios + 1} failures=${failures.length}`);
  for (const f of failures.slice(0, 5)) console.log(util.inspect(f, { depth: 6 }));
  process.exitCode = failures.length ? 1 : 0;
})();
EOF
