const { createChannelNotifier } = require('./channelNotifier');
const { emailChannel } = require('./emailChannel');
const { smsChannel } = require('./smsChannel');
const { slackChannel } = require('./slackChannel');
const { inAppChannel } = require('./inAppChannel');

// Registry entries were classes. They are now plain (non-arrow) functions that
// return a notifier, so both `registry.email(options)` and
// `new registry.email(options)` keep working.
function notifierFactory(definition) {
  return function createChannel(options = {}) {
    return createChannelNotifier(definition, options);
  };
}

const registry = {
  email: notifierFactory(emailChannel),
  sms: notifierFactory(smsChannel),
  slack: notifierFactory(slackChannel),
  inapp: notifierFactory(inAppChannel)
};

function createNotifier(channel, options = {}) {
  // hasOwn keeps inherited keys such as "constructor" from resolving to a channel.
  const factory = Object.hasOwn(registry, channel) ? registry[channel] : undefined;
  if (!factory) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};

